const clip = $json;

return {
  vod_url: clip.vod_url || `https://twitch.tv/videos/${clip.vod_id}`,
  start_time: clip.start_time,
  end_time: clip.end_time,
  duration: clip.end_time - clip.start_time,
  streamer: clip.streamer,
  game: clip.game,
  clip_id: clip.clip_id || `clip_${clip.vod_id}_${clip.start_time}`,
  title: clip.title,
  reason: clip.reason
};

// Generate FFmpeg command for clip extraction + vertical crop + captions
const { vod_url, start_time, end_time, duration, clip_id, streamer, title } = $json;

const outputPath = `/output/${clip_id}.mp4`;
const captionPath = `/temp/${clip_id}_captions.srt`;
const watermarkPath = `/scripts/assets/watermark.png`;

// Step 1: Extract clip with vertical crop (9:16)
// Using yt-dlp to download segment + ffmpeg to process
const cmd = `
  yt-dlp -f "bestvideo[height<=1080]+bestaudio/best" \
    --download-sections "*${start_time}-${end_time}" \
    -o "/temp/${clip_id}_raw.%(ext)s" \
    "${vod_url}" &&

  ffmpeg -y -i "/temp/${clip_id}_raw.mp4" \
    -vf "crop=ih*9/16:ih:(ow-iw)/2:0,scale=1080:1920:force_original_aspect_ratio=decrease,pad=1080:1920:(ow-iw)/2:(oh-ih)/2:black" \
    -af "loudnorm=I=-16:TP=-1.5:LRA=11" \
    -c:v libx264 -preset fast -crf 23 -c:a aac -b:a 128k \
    "/temp/${clip_id}_cropped.mp4"
`;

return { ...$json, cmd, outputPath, captionPath, croppedPath: `/temp/${clip_id}_cropped.mp4` };

// Generate captions using Whisper.cpp
const { croppedPath, clip_id, captionPath } = $json;

const cmd = `whisper-cli -m /models/ggml-base.en.bin -f "${croppedPath}" -osrt -of "${captionPath.replace('.srt', '')}"`;

return { ...$json, captionCmd: cmd };

// Final render: burn captions + watermark + branding
const { croppedPath, captionPath, clip_id, streamer, title, outputPath } = $json;
const watermarkPath = '/scripts/assets/watermark.png';

const captionStyle = "Fontsize=24,Fontcolor=white,Outline=2,OutlineColour=black,Alignment=2,MarginV=150";

// Watermark: scale to 15% of width, place bottom-right with padding
const cmd = `ffmpeg -y -i "${croppedPath}" -i "${watermarkPath}" \
  -filter_complex "[1:v]scale=iw*0.15:ih*0.15[wm]; \
  [0:v]subtitles='${captionPath}':force_style='${captionStyle}', \
    drawtext=text='@${streamer}':fontsize=36:fontcolor=white:x=w-tw-20:y=20:box=1:boxcolor=black@0.5:boxborderw=5, \
    drawtext=text='${title.substring(0, 50)}':fontsize=28:fontcolor=white:x=(w-tw)/2:y=h-100:box=1:boxcolor=black@0.5:boxborderw=5[base]; \
  [base][wm]overlay=W-w-20:H-h-20" \
  -c:v libx264 -preset fast -crf 22 -c:a aac -b:a 128k \
  -movflags +faststart \
  "${outputPath}"`;

return { ...$json, finalCmd: cmd };

// Upload to R2 / S3 and return public URL
const { outputPath, clip_id } = $json;
const fs = require('fs');
if (!fs.existsSync(outputPath)) {
  throw new Error('Output file not found');
}

const stats = fs.statSync(outputPath);
const fileSizeMB = (stats.size / 1024 / 1024).toFixed(2);

// Upload to R2 / S3 using the AWS CLI (pre-installed on VPS)
// Returns the public URL after successful upload
const { execSync } = require('child_process');
const r2Bucket = $env.R2_BUCKET_NAME || 'tiktok-clips';
const r2PublicUrl = $env.R2_PUBLIC_URL || '';
const s3Key = `clips/${clip_id}.mp4`;

let video_url = outputPath; // fallback to local path
try {
  execSync(
    `aws s3 cp "${outputPath}" "s3://${r2Bucket}/${s3Key}" --acl public-read --region auto`,
    { stdio: 'pipe', timeout: 300000 }
  );
  video_url = r2PublicUrl ? `${r2PublicUrl.replace(//$/, '')}/${s3Key}` : `https://${r2Bucket}.r2.cloudflarestorage.com/${s3Key}`;
} catch (err) {
  // Upload failed — still mark ready but note the failure
  console.error('R2 upload failed:', err.message);
  video_url = outputPath;
}

return {
  ...$json,
  video_path: outputPath,
  video_url,
  file_size_mb: fileSizeMB,
  status: 'ready_to_post'
};
